async function request(name,body){const c=config();if(!c)throw Error('ยังไม่ได้ตั้งค่า Supabase');const res=await fetch(c.url+'/rest/v1/rpc/'+name,{method:'POST',signal:AbortSignal.timeout(30000),headers:{apikey:c.key,'Content-Type':'application/json'},body:JSON.stringify(body)});let data;try{data=await res.json();}catch{throw Error('Supabase ตอบกลับไม่ถูกต้อง HTTP '+res.status);}if(!res.ok){const message=data.message||data.error_description||'เชื่อมต่อฐานข้อมูลไม่สำเร็จ HTTP '+res.status;throw Error(/statement timeout/i.test(message)?'ฐานข้อมูลใช้เวลานานเกินกำหนด กรุณาโหลดข้อมูลล่าสุดและตรวจสถานะก่อนลองอีกครั้ง':message);}return data;}
const loadCloud=()=>request('pn2_load_workspace',{});
const saveCloud=(state,revision)=>request('pn2_save_workspace',{payload:state,expected_revision:revision});
