  const key=group==='projects'||group==='contractRegistry'?contractIdentity(item):group==='reports'?reportIdentity(item)+'|'+(item.sourceSheet||item.title||''):item.name;
  if(seen.has(key))throw Error('รายการซ้ำในไฟล์: '+group+' '+key);seen.add(key);
  const reportMatches=group==='reports'?old.filter(x=>reportIdentity(x)===reportIdentity(item)):[];const reportMatch=reportMatches.find(x=>(item.sourceSheet&&x.sourceSheet===item.sourceSheet)||x.title===item.title)||(reportMatches.length===1&&items.filter(x=>reportIdentity(x)===reportIdentity(item)).length===1?reportMatches[0]:null);const match=old.find(x=>x.id===item.id)||(group==='reports'?reportMatch:old.find(x=>(group==='projects'||group==='contractRegistry'?contractIdentity(x):x.name)===key));
