export function importHistoryCSV(runs){const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"',value=v=>v===null?'ไม่มีค่า':typeof v==='object'?JSON.stringify(v):String(v);const rows=[['ไฟล์','วันเวลา','รายการ / ช่อง','ค่าเดิม','ค่าปัจจุบัน','สถานะ'],...runs.flatMap(r=>r.changes.map(c=>[r.fileName,r.at,c.path.split(' / ').map(x=>importFieldLabels[x]||r.labels?.[x]||x).join(' / '),value(c.before),value(c.after),c.kind==='added'?'เพิ่มใหม่':c.kind==='removed'?'เอาออกจากชุดปัจจุบัน':'อัปเดตจากไฟล์']))];return '\ufeff'+rows.map(row=>row.map(q).join(',')).join('\r\n');}
