export function updateMasterReferences(s,key,item){for(const p of s.projects||[]){if(key==='contractors'&&p.contractorId===item.id)p.contractor=item.name;if(key==='supervisors'&&p.supervisorId===item.id)p.supervisor=item.name;if(key==='workNames'&&p.workNameId===item.id){p.title=item.name;p.workTypeId=item.typeId||'';}}for(const r of s.contractRegistry||[]){if(key==='workNames'&&r.workNameId===item.id){r.title=item.name;r.workTypeId=item.typeId||'';}if(key==='workCodes'&&r.workCodeId===item.id)r.workCode=item.name;if(key==='budgetAccounts'&&r.budgetAccountId===item.id)r.budgetAccount=item.name;}}
export function changeDraftWeek(s,id,range){const r=s.reports.find(x=>x.id===id);if(!r||r.locked)throw Error('แก้ช่วงวันที่ได้เฉพาะรายงานฉบับร่าง');if(s.reports.some(x=>x.id!==id&&x.end&&x.end>r.end&&(x.funding||'DOH')===(r.funding||'DOH')&&x.year===r.year))throw Error('มีสัปดาห์ถัดไปแล้ว กรุณาแก้เฉพาะฉบับร่างล่าสุด');if(days(range.end,range.start)!==6||new Date(range.end+'T00:00:00Z').getUTCDay()!==1)throw Error('ช่วงรายงานต้องเป็นอังคาร–จันทร์ครบ7วัน');if(s.reports.some(x=>x.id!==id&&x.start===range.start&&x.year===r.year&&(x.funding||'DOH')===(r.funding||'DOH')))throw Error('มีสัปดาห์ที่ใช้ช่วงวันที่นี้แล้ว');const otherEnds=s.reports.filter(x=>x.id!==id&&x.end&&(x.funding||'DOH')===(r.funding||'DOH')&&(x.year===r.year||(!x.year&&Object.keys(x.entries||{}).some(pid=>s.projects.some(p=>p.id===pid&&p.year===r.year))))).map(x=>x.end);if(otherEnds.some(end=>end>=range.start))throw Error('ช่วงใหม่ต้องอยู่หลังรายงานก่อนหน้าของกลุ่มงบและปีนี้');for(const [pid,e]of Object.entries(r.entries)){const prev=s.reports.filter(x=>x.id!==id&&x.end&&x.end<range.start&&x.entries[pid]).sort((a,b)=>b.end.localeCompare(a.end))[0]?.entries[pid];e.weekly=+(Number(e.actual)-Number(prev?.actual||0)).toFixed(2);validateEntry(e,prev||{actual:0});e.confirmed=false;}Object.assign(r,range,{reference:range.end,modifiedAt:new Date().toISOString()});return r;}

