const field=(label,name,value='',type='text',extra='')=>`<label class="field ${type==='textarea'?'wide':''}">${label}${type==='textarea'?`<textarea class="resize-none" name="${name}" ${extra}>${esc(value)}</textarea>`:`<input type="${type}" name="${name}" value="${esc(value)}" ${extra}>`}</label>`;
const selectField=(label,name,options,value)=>`<label class="field">${label}<select name="${name}">${options.map(o=>`<option value="${esc(o.value??o)}" ${String(o.value??o)===String(value)?'selected':''}>${esc(o.label??o)}</option>`).join('')}</select></label>`;
async function mutate(action,fn,importSource){if(busy)throw Error('กำลังบันทึก กรุณารอสักครู่');busy=true;const next=clone(state);try{fn(next);if(next.projects.some(p=>p.category==='UNCATEGORIZED')&&!next.categories.some(c=>c.id==='UNCATEGORIZED'))next.categories.push({id:'UNCATEGORIZED',name:'ยังไม่ระบุหมวดเดิม'});normalizeState(next);next.audit.unshift({id:crypto.randomUUID(),at:new Date().toISOString(),action});next.audit=next.audit.slice(0,2000);if(importSource)recordImport(state,next,importSource);if(cloudMode){const result=importSource?await cloud.importCloud(next,state.revision||0,importSource):await cloud.saveCloud(next,state.revision||0);if(result.document)Object.assign(next,result.document);next.revision=result.revision;}if(!cloudMode)next.revision=(state.revision||0)+1;try{await writeStore(next,cloudMode?undefined:(state.revision||0));}catch(e){if(!cloudMode)throw Error('พื้นที่จัดเก็บเต็ม กรุณาสำรองข้อมูลหรือต่อ Supabase');toast('บันทึกบน Supabase แล้ว แต่สำรองบนอุปกรณ์ไม่สำเร็จ',true);}state=next;if(importSource)importHistoryPage=1;render();toast('บันทึกเรียบร้อย');}finally{busy=false;}}
function previousEntry(r,id){const e=state.reports.filter(x=>x.id!==r.id&&x.end&&r.start&&x.end<r.start&&x.entries[id]).sort((a,b)=>b.end.localeCompare(a.end))[0]?.entries[id];return e?{...e,paymentDate:e.paymentDate||parsePaymentDate(e.note)}:undefined;}
const activeRows=()=>rowsFor({...state,activeFunding:funding},report(),year);
function header(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><div class="sub">${sub}</div></div><div class="actions">${actions}</div></div>`;}
function periodBar(showWeek=true){return `<div class="period-bar"><div class="period-control"><span class="period-label">กลุ่มงบ</span><select id="funding-select">${state.fundingSources.map(x=>`<option value="${x.id}" ${x.id===funding?'selected':''}>${esc(x.name)}</option>`).join('')}</select><span class="period-label">ปีงบประมาณ</span><select id="year">${state.years.map(y=>`<option value="${y}" ${y===year?'selected':''}>${y}</option>`).join('')}</select>${showWeek?`<span class="period-label">สัปดาห์รายงาน</span><select id="report-select">${state.reports.filter(r=>r.id!=='EMPTY'&&(r.funding||'DOH')===funding&&(r.year===year||(!r.year&&rowsFor({...state,activeFunding:funding},r,year).length))).map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${esc(weekLabel(r)+' · '+(r.end?fmt(r.start)+' – '+fmt(r.end):'ต้นฉบับ'))}</option>`).join('')}</select>`:''}</div>${showWeek?`<div class="sub"><span class="live-dot"></span>${report().locked?'รายงานเก็บประวัติแล้ว':'ฉบับร่าง · กำลังอัปเดต'}</div>`:''}</div>`;}
function stat(label,n,foot,icon,cls=''){return `<div class="stat ${cls}"><div class="stat-label">${label}</div><span class="stat-icon">${icon}</span><div class="stat-number">${n}<small>โครงการ</small></div><div class="stat-foot">${foot}</div></div>`;}
function dashboard(){const rows=activeRows(),done=rows.filter(x=>complete(x.e)).length,paid=rows.filter(x=>x.e.payment==='เบิกจ่ายแล้ว').length,ongoing=rows.length-done,late=rows.filter(x=>!complete(x.e)&&expired(x.p)).length,pct=rows.length?Math.round(done/rows.length*100):0;const hist=state.reports.filter(r=>r.entries&&rowsFor({...state,activeFunding:funding},r,year).length).slice(0,6).reverse();return header('ภาพรวมโครงการ','ติดตามความก้าวหน้าและจัดการรายงานประจำสัปดาห์ในที่เดียว',`<button class="btn" data-action="preview">↗ ดูรายงาน</button><button class="btn primary" data-action="new-report">＋ สร้างสัปดาห์รายงาน</button>`)+periodBar()+`<div class="stats">${stat('โครงการทั้งหมด',rows.length,'ปีงบประมาณ '+year,'▦')}${stat('ดำเนินการแล้วเสร็จ',done,`<strong>${pct}%</strong> ของโครงการทั้งหมด`,'✓')}${stat('อยู่ระหว่างดำเนินการ',ongoing,'ติดตามและอัปเดตผลงานประจำสัปดาห์','◷','orange')}${stat('สัญญาที่ต้องติดตาม',late,'ยังไม่แล้วเสร็จและเลยกำหนด ณ วันนี้','⚑','red')}</div><div class="overview-grid"><div class="card"><div class="card-header"><div><h2>แนวโน้มความก้าวหน้า</h2><div class="sub">ค่าเฉลี่ยรายโครงการ · 6 สัปดาห์ล่าสุดใน Excel</div></div><div class="legend"><span><i></i>แผน</span><span><i class="dark"></i>ผลงาน</span></div></div><div class="bar-chart"><span class="chart-y" style="top:5px">100</span><span class="chart-y" style="top:75px">50</span><span class="chart-y" style="bottom:23px">0</span>${hist.map(r=>{const x=rowsFor({...state,activeFunding:funding},r,year),avg=k=>x.reduce((n,v)=>n+v.e[k],0)/x.length;return `<div class="group"><div class="bar" title="แผน ${avg('plan').toFixed(2)}%" style="height:${avg('plan')}%"></div><div class="bar actual" title="ผลงาน ${avg('actual').toFixed(2)}%" style="height:${avg('actual')}%"></div><label>${esc(weekLabel(r))}</label></div>`;}).join('')}</div><div class="chart-note">ค่าเฉลี่ยไม่ถ่วงน้ำหนัก • อ้างอิงข้อมูลที่นำเข้าจากแต่ละแผ่นงาน</div></div><div class="card"><div class="card-header"><div><h2>สถานะโครงการ</h2><div class="sub">สรุปผลการดำเนินงานในสัปดาห์ที่เลือก</div></div><span class="badge">${rows.length} โครงการ</span></div><div class="donut-layout"><div class="donut" style="background:conic-gradient(#347962 0 ${pct}%,#e9bd71 ${pct}% 100%)"><div class="donut-inner">${pct}%<small>ดำเนินการแล้วเสร็จ</small></div></div><div class="donut-legend"><div><i></i>แล้วเสร็จ<b>${done}</b></div><div><i style="background:#e9bd71"></i>กำลังดำเนินการ<b>${ongoing}</b></div><div><i style="background:#b8cbbd"></i>เบิกจ่ายแล้ว<b>${paid}</b></div></div></div></div></div><div class="insight"><span style="font-size:22px">✧</span><div><strong>ผู้ช่วยติดตามงาน</strong><div class="sub">${late?`มี ${late} โครงการที่เลยกำหนดสัญญาและยังไม่แล้วเสร็จ ควรตรวจหนังสือขยายอายุสัญญา`:'ไม่พบงานที่เลยกำหนดและยังไม่แล้วเสร็จ'} · ${rows.filter(x=>x.e.plan>x.e.actual).length} โครงการมีผลงานต่ำกว่าแผน</div></div><button class="text-link" style="margin-left:auto;white-space:nowrap" data-action="alerts">ดูรายละเอียด ↗</button></div>${projectTable(rows,false,true)}`;}
function projectTable(rows,weekly=false,dash=false){const counts={all:rows.length,ongoing:rows.filter(x=>!complete(x.e)).length,deliver:rows.filter(x=>statusKey(x.e)==='deliver').length,pay:rows.filter(x=>statusKey(x.e)==='pay').length,paid:rows.filter(x=>x.e.payment==='เบิกจ่ายแล้ว').length};const filtered=rows.slice().sort(weekly&&weeklySort.key?(a,b)=>compareData(a,b,weeklySort.key,weeklySort.dir):sortRows).filter(({p,e})=>(filter==='all'||filter===statusKey(e))&&(!category||p.workTypeId===category)&&(!query||(p.title+p.contract+p.contractor+p.id).toLowerCase().includes(query.toLowerCase())));const size=weekly?100:dash?5:12;const max=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(page,max);const slice=filtered.slice((page-1)*size,page*size);return `<div class="card table-card"><div class="table-top"><div><h2>${weekly?'บันทึกผลงานประจำสัปดาห์':'ทะเบียนโครงการ'}</h2><div class="sub">${weekly?'ทบทวนทุกโครงการก่อนยืนยันและปิดรายงาน':'ข้อมูลสัญญาและความก้าวหน้าในสัปดาห์รายงานที่เลือก'}</div></div>${weekly?`<span class="review-count">ยืนยันแล้ว ${rows.filter(x=>x.e.confirmed).length}/${rows.length}</span>`:`<button class="text-link" data-view="projects">ดูทะเบียนทั้งหมด ↗</button>`}</div>${weekly?'':`<div class="tabs">${[['all','ทั้งหมด'],['ongoing','กำลังดำเนินการ'],['deliver','รอส่งมอบงาน'],['pay','รอเบิกจ่าย'],['paid','เบิกจ่ายแล้ว']].map(([v,t])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${t}<b>${counts[v]}</b></button>`).join('')}</div>`}<div class="filters"><input id="search" class="search" placeholder="⌕ ค้นหาชื่องาน เลขสัญญา หรือผู้รับจ้าง" value="${esc(query)}"><select id="category-filter"><option value="">ทุกประเภทงาน</option>${state.workTypes.filter(c=>!c.archived).map(c=>`<option value="${c.id}" ${category===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span class="sub" style="margin-left:auto">${filtered.length} รายการ</span></div><div class="table-scroll"><table><thead><tr>${weekly?sortHead('เลขสัญญา','p.contract','weekly',weeklySort)+sortHead('งาน / ผู้รับจ้าง','p.title','weekly',weeklySort):'<th>สัญญา / รหัส</th><th>โครงการ / ผู้รับจ้าง</th>'}${weekly?[['แผนสะสม %','e.plan'],['ผลงานสัปดาห์ %','e.weekly'],['ผลงานสะสม %','e.actual'],['หมายเหตุ','e.note'],['การเบิกจ่าย','e.payment']].map(([l,k])=>sortHead(l,k,'weekly',weeklySort)).join('')+'<th>ยืนยัน</th>':'<th>ระยะเวลาสัญญา</th><th>ความก้าวหน้า</th><th>สถานะ</th><th>จัดการ</th>'}</tr></thead><tbody>${slice.map(({p,e})=>`<tr class="${statusKey(e)==='paid'?'paid':statusKey(e)==='deliver'?'waiting-delivery':statusKey(e)==='pay'?'waiting-payment':''}" data-id="${p.id}"><td><div class="code">${esc(p.contract)}</div><div class="sub">${esc(p.id)}</div></td><td><button class="name contract-open" data-edit="${p.id}" title="ดูข้อมูลสัญญา">${esc(p.title)}</button><div class="sub">${esc(p.contractor)}</div></td>${weekly?['plan','weekly','actual'].map(k=>`<td><input aria-label="${k} ${esc(p.contract)}" data-entry="${k}" class="weekly-input" type="number" min="0" max="100" step="0.01" value="${e[k]}" ${report().locked?'disabled':''}>${report().locked?`<button class="text-link" data-amend-entry="${p.id}">แก้ไข</button>`:''}</td>`).join('')+`<td><input aria-label="หมายเหตุ ${esc(p.contract)}" data-entry="note" class="weekly-note" value="${esc(e.note)}" ${report().locked?'disabled':''}></td><td><select aria-label="การเบิกจ่าย ${esc(p.contract)}" data-entry="payment" class="weekly-select" ${report().locked?'disabled':''}>${['รอส่งมอบงาน','รอเบิกจ่าย','เบิกจ่ายแล้ว'].map(s=>`<option ${s===e.payment?'selected':''}>${s}</option>`).join('')}</select><button class="text-link" data-contract-dates="${p.id}">${e.paymentDate||e.deliveryDate||e.acceptanceDate?'แก้ไขวันที่':'บันทึกวันที่'}</button></td><td><input aria-label="ยืนยัน ${esc(p.contract)}" data-entry="confirmed" type="checkbox" ${e.confirmed?'checked':''} ${report().locked?'disabled':''}>${report().locked?`<button class="text-link" data-amend-entry="${p.id}">แก้ไข</button>`:''}</td>`:`<td>${fmt(p.end)}<div class="sub">${effectiveDays(p)} วัน · ดำเนินการ ${report().reference?elapsed(p,e,report().reference):'ไม่ระบุ'} วัน</div></td><td><div class="progress"><div class="track"><span style="width:${e.actual}%"></span></div>${Number(e.actual).toFixed(2)}%</div><div class="sub">แผน ${Number(e.plan).toFixed(2)}%</div></td><td><span class="pill ${complete(e)?'':expired(p)?'red':'warn'}">${complete(e)?'แล้วเสร็จ':'อยู่ระหว่างดำเนินการ'}</span><div class="sub">${e.payment}</div></td><td><button class="edit" data-edit="${p.id}">รายละเอียด ↗</button></td>`}</tr>`).join('')||'<tr><td colspan="9" class="empty">ไม่พบโครงการในเงื่อนไขที่เลือก</td></tr>'}</tbody></table></div><div class="table-foot"><span>แสดง ${filtered.length?((page-1)*size+1):0}–${Math.min(page*size,filtered.length)} จาก ${filtered.length} รายการ</span><div class="actions"><button data-page="${page-1}" ${page<=1?'disabled':''}>←</button><span>หน้า ${page} / ${max}</span><button data-page="${page+1}" ${page>=max?'disabled':''}>→</button></div></div></div>`;}
function weekly(){const importButton='<button class="btn" data-action="import-weekly">↑ นำเข้าชุดรายสัปดาห์ JSON</button>';if(report().id==='EMPTY'||(report().funding||'DOH')!==funding||(report().year&&report().year!==year))return header('อัปเดตรายสัปดาห์','ยังไม่มีรายงานของกลุ่มงบและปีที่เลือก',`${importButton}<button class="btn primary" data-action="new-report">＋ สร้างสัปดาห์รายงาน</button>`)+periodBar()+'<div class="notice">เพิ่มสัญญาของกลุ่มงบนี้ แล้วสร้างสัปดาห์รายงานเพื่อเริ่มบันทึก</div>';return header('อัปเดตรายสัปดาห์','วันอ้างอิงคำนวณ: '+fmt(report().reference)+' · สัปดาห์อังคาร–จันทร์',`${importButton}<button class="btn" data-action="preview">ดูตัวอย่างรายงาน</button>${report().locked?'<button class="btn" data-action="amend-report">แก้ไขรายงาน</button><button class="btn primary" data-action="new-report">＋ สร้างสัปดาห์ถัดไป</button>':'<button class="btn" data-action="carry">ดึงค่าสัปดาห์ก่อน</button><button class="btn" data-action="confirm-unchanged">ยืนยันรายการที่ไม่เปลี่ยน</button><button class="btn primary" data-action="lock">✓ ตรวจสอบและปิดรายงาน</button>'}`)+periodBar()+(report().locked?'<div class="notice">รายงานนี้เก็บเป็นประวัติแล้ว สามารถดูและส่งออกได้ กดแก้ไขรายงานเพื่อปรับข้อมูลย้อนหลังได้ ระบบเก็บประวัติให้อัตโนมัติ</div>':'<div class="notice">ผลงานสะสม = ผลงานสะสมสัปดาห์ก่อน + ผลงานรายสัปดาห์ • แผนสะสมคงค่าจากสัปดาห์ก่อนจนกว่าจะปรับเอง • ยืนยันทุกแถวก่อนปิดรายงาน</div>')+(!report().locked?`<div class="week-management"><button class="btn" data-action="edit-week">${miniIcon('edit')} แก้ไขช่วงสัปดาห์</button><button class="btn danger" data-action="cancel-week">${miniIcon('delete')} ยกเลิกสัปดาห์</button></div>`:'')+weeklySummary(activeRows())+projectTable(activeRows(),true);}
function projects(){return header('ทะเบียนสัญญา','ข้อมูลสัญญากลางสำหรับรายงานของแต่ละกลุ่มงบและปีงบประมาณ',`<button class="btn" data-action="convert-g3">แปลง Excel ก-3 → CSV</button><button class="btn" data-action="import-registry-csv">นำเข้า CSV</button><button class="btn" data-action="export-registry-csv">ส่งออก CSV</button><button class="btn primary" data-action="new-project">＋ เพิ่มสัญญา</button>`)+periodBar(false)+registrySummary()+registryTable();}

function reports(){const list=state.reports.filter(r=>r.id!=='EMPTY'&&((r.funding||'DOH')===funding)&&rowsFor({...state,activeFunding:funding},r,year).length&&(!archiveQuery||(weekLabel(r)+' '+fmt(r.start)+' '+fmt(r.end)).includes(archiveQuery))).sort((a,b)=>(b.end||'').localeCompare(a.end||''));const max=Math.max(1,Math.ceil(list.length/10));archivePage=Math.min(max,archivePage);const shown=list.slice((archivePage-1)*10,archivePage*10);return header('คลังรายงาน','รายงานประจำสัปดาห์ เรียงจากล่าสุดก่อน',`<button class="btn primary" data-action="new-report">＋ สร้างสัปดาห์รายงาน</button>`)+archiveFilters()+`<div class="card"><div class="filters"><input id="archive-search" class="search" aria-label="ค้นหารายงาน" placeholder="ค้นหาสัปดาห์หรือช่วงวันที่" value="${esc(archiveQuery)}">${archiveQuery?'<button class="btn" id="clear-archive" aria-label="ล้างคำค้น">ล้าง</button>':''}<span class="sub">${list.length} รายงาน</span></div><div class="table-scroll"><table class="archive-table"><thead><tr><th>สัปดาห์</th><th>ช่วงวันที่</th><th>จำนวนงาน</th><th>สถานะ</th><th></th></tr></thead><tbody>${shown.map(r=>`<tr><td><strong>${esc(weekLabel(r))}</strong></td><td>${r.end?fmt(r.start)+' – '+fmt(r.end):'ต้นฉบับไม่ระบุช่วงวันที่'}${r.modifiedAt?`<button class="amended-indicator" data-amend-info="${r.id}" aria-label="ดูวันที่แก้ไขล่าสุด">✎ แก้ไขแล้ว</button>`:''}</td><td>${rowsFor({...state,activeFunding:funding},r,year).length}<span class="mobile-unit"> งาน</span></td><td><span class="pill ${r.locked?'':'warn'}">${r.locked?'เก็บรายงานแล้ว':'ฉบับร่าง'}</span></td><td><button class="btn" data-open-report="${r.id}">เปิดรายงาน</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">ไม่พบรายงาน ลองเปลี่ยนปี กลุ่มงบ หรือคำค้น</td></tr>'}</tbody></table></div><div class="table-foot"><span>หน้า ${archivePage} / ${max}</span><div class="actions"><button class="btn" data-archive-page="${archivePage-1}" ${archivePage===1?'disabled':''}>ก่อนหน้า</button><button class="btn" data-archive-page="${archivePage+1}" ${archivePage===max?'disabled':''}>ถัดไป</button></div></div></div>`;}
function archiveFilters(){return `<div class="period-bar"><div class="period-control">${selectField('กลุ่มงบ','archiveFunding',state.fundingSources.map(x=>({value:x.id,label:x.name})),funding)}${selectField('ปีงบประมาณ','archiveYear',state.years,year)}</div></div>`;}
function bindArchive(){const f=$('[name=archiveFunding]'),y=$('[name=archiveYear]');if(f){f.value=funding;f.onchange=()=>{funding=f.value;archivePage=1;render();};}if(y){y.value=String(year);y.onchange=()=>{year=+y.value;archivePage=1;render();};}$('#archive-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;archiveQuery=e.target.value;archivePage=1;render();$('#archive-search').focus();$('#archive-search').setSelectionRange(pos,pos);});$('#clear-archive')?.addEventListener('click',()=>{archiveQuery='';archivePage=1;render();$('#archive-search').focus();});$$('[data-archive-page]').forEach(b=>b.onclick=()=>{archivePage=+b.dataset.archivePage;render();});$$('[data-amend-info]').forEach(b=>b.onclick=()=>{const r=state.reports.find(r=>r.id===b.dataset.amendInfo);modal('แก้ไขรายงานแล้ว',`<p>แก้ไขล่าสุด ${esc(new Date(r.modifiedAt).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}))}</p><p class="sub">แก้ไขแล้ว ${r.amendedVersion||1} ครั้ง</p>`);});}

function legacyCatalog(){return header('หมวดหมู่และปีงบประมาณ','ใช้รหัสข้อมูลถาวร อ้างอิงร่วมกันได้ทุกปีงบประมาณ')+`<div class="grid2"><div class="card"><div class="card-header"><h2>ประเภทงาน</h2><button class="btn" data-action="new-category">＋ เพิ่มประเภท</button></div>${state.categories.map(c=>`<div class="catalog-item"><div>${esc(c.name)}<br><code>${c.id}</code></div><div class="actions"><button class="text-link" data-edit-category="${c.id}">แก้ไข</button><button class="text-link danger-text" data-delete-category="${c.id}">ลบ</button></div></div>`).join('')}</div><div class="card"><div class="card-header"><h2>ปีงบประมาณ</h2><button class="btn" data-action="new-year">＋ เพิ่มปี</button></div>${state.years.map(y=>`<div class="catalog-item"><div>ปีงบประมาณ ${y}<br><code>FY-${y}</code></div><span class="sub">${state.projects.filter(p=>p.year===y).length} สัญญา</span><button class="text-link danger-text" data-delete-year="${y}">ลบ</button></div>`).join('')}<h3 style="margin-top:25px">หัวข้อข้อมูลเพิ่มเติม</h3><p class="hint">เพิ่มช่องข้อความในทะเบียนสัญญา เช่น ทางหลวง ตอนควบคุม วงเงิน ระบบเก็บเข้าฐานข้อมูลและประวัติรายงาน</p><button class="btn" data-action="new-custom-field">＋ เพิ่มหัวข้อ</button>${(state.settings.customFields||[]).map(c=>`<div class="catalog-item"><span>${esc(c.name)}<br><code>${c.id}</code></span><button class="text-link danger-text" data-remove-field="${c.id}">ซ่อนหัวข้อ</button></div>`).join('')}<p class="hint">ปีงบประมาณแยกจากปีในเลขสัญญาและปีที่แสดงในชื่อรายงาน ไม่ย้ายข้อมูลข้ามปีอัตโนมัติ</p></div></div>`;}
function weeklyImportDialog(){
 const targetFunding=funding,targetYear=year;let incoming,fileName='';
 modal('นำเข้ารายสัปดาห์ · '+fundingName(state,targetFunding)+' '+targetYear,`<form id="weekly-import-form"><div class="notice">แทนเฉพาะ ${esc(fundingName(state,targetFunding))} ปี ${targetYear} รวมรายงานที่ปิดแล้ว ข้อมูลอีกกลุ่มและอีกปีคงเดิม พร้อมเก็บประวัติการเปลี่ยนแปลง</div><label class="field">ไฟล์ JSON ของกลุ่มนี้<input id="weekly-import-file" type="file" accept=".json" required></label><button class="btn" type="button" id="weekly-import-read">อ่านและตรวจข้อมูล</button><div id="weekly-import-preview"></div><p class="form-error" role="alert"></p></form>`);
 const form=$('#weekly-import-form');$('#weekly-import-file').onchange=()=>{incoming=null;$('#weekly-import-preview').innerHTML='';};
 $('#weekly-import-read').onclick=async()=>{form.querySelector('.form-error').textContent='';try{const file=$('#weekly-import-file').files[0];if(!file)throw Error('เลือกไฟล์ก่อน');if(file.size>30000000)throw Error('JSON ต้องไม่เกิน30MB');const data=JSON.parse(await file.text());prepareWeeklyImport(state,data,targetFunding,targetYear);incoming=data;fileName=file.name;$('#weekly-import-preview').innerHTML=`<div class="notice">${data.projects.length} สัญญา · ${data.reports.length} รายงาน · ${Object.values(data.reports).reduce((n,r)=>n+Object.keys(r.entries).length,0)} รายการผลงาน</div><div class="dialog-actions"><button class="btn primary" type="button" id="weekly-import-commit">นำเข้าทับกลุ่มนี้</button></div>`;$('#weekly-import-commit').onclick=()=>confirmAction('ยืนยันนำเข้าทับ · '+fundingName(state,targetFunding)+' '+targetYear,'แทนชุดรายสัปดาห์เฉพาะกลุ่มงบและปีนี้ เก็บค่าเดิมในประวัติ และไม่เปลี่ยนข้อมูลของอีกกลุ่ม',async()=>{await mutate('นำเข้ารายสัปดาห์ '+fundingName(state,targetFunding)+' '+targetYear,s=>Object.assign(s,prepareWeeklyImport(state,incoming,targetFunding,targetYear)),{fileName,format:'JSON'});funding=targetFunding;year=targetYear;selected=state.reports.filter(r=>(r.funding||'DOH')===funding&&r.year===year).sort((a,b)=>(b.end||'').localeCompare(a.end||''))[0]?.id;view='weekly';render();});}catch(e){incoming=null;$('#weekly-import-preview').innerHTML='';showFormError(form,e.message);}};
}
let importHistoryPage=1;
function audit(){return header('ประวัติการเปลี่ยนแปลง','ค่าเดิมและค่าปัจจุบันจากการนำเข้า CSV / JSON','<button class="btn" data-action="export-import-history">↓ ส่งออกประวัติ CSV</button>')+`<div class="card">${importHistoryHTML(state.importHistory||[],importHistoryPage)}</div><div class="card">${state.audit.length?state.audit.map(a=>`<div class="audit-item"><span>${esc(a.action)}</span><span class="sub">${new Date(a.at).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})}</span></div>`).join(''):'<div class="empty">ยังไม่มีการแก้ไขหลังนำเข้าข้อมูล</div>'}</div>`;}
function settings(){return header('ตั้งค่าระบบ','ตั้งค่ารายงาน สำรองข้อมูล และเชื่อมต่อ Supabase')+`<div class="grid2"><div><div class="card settings-section"><h2>รูปแบบรายงาน</h2><form id="settings-form"><div class="form-grid" style="margin-top:20px">${field('หน่วยงาน','organization',state.settings.organization,'text','required')}${field('ชื่อระบบ','systemName',state.settings.systemName,'text','required')}<label class="field">โลโก้ PNG (ไม่เกิน 500 KB)<input id="logo-file" type="file" accept="image/png"><span class="hint">ใช้ทั้งหน้าเว็บและไอคอนแท็บ</span></label>${state.settings.logo?`<div class="field"><img src="${state.settings.logo}" alt="โลโก้ปัจจุบัน" style="width:64px;height:64px;object-fit:contain"><label><input type="checkbox" name="removeLogo"> ลบโลโก้</label></div>`:''}${field('ชื่อรายงานกรมทางหลวง','titleDOH',state.settings.reportTitles.DOH,'text','required')}${field('ชื่อรายงานงบจังหวัด','titleProvince',state.settings.reportTitles.PROVINCE,'text','required')}<div class="field">สัปดาห์รายงาน<input value="อังคาร–จันทร์ · ใช้จันทร์ท้ายรอบ" disabled></div></div><div class="dialog-actions"><button class="btn primary" type="submit">บันทึกการตั้งค่า</button></div></form></div><div class="card"><h2>สำรองและย้ายข้อมูล</h2><p class="sub">สำรองทะเบียนสัญญา รายงานทุกสัปดาห์ และประวัติ เป็น JSON</p><div class="actions"><button class="btn" data-action="backup">↓ สำรองข้อมูลทั้งหมด</button><button class="btn primary" data-action="restore">↑ นำเข้าข้อมูล JSON</button></div><p class="hint">ข้อมูลเดิมนำเข้า 61 สัญญา และ 57 รายงานจาก Excel • ไฟล์สำรองมีข้อมูลจริง ควรเก็บในพื้นที่ที่จำกัดสิทธิ์</p></div></div><div class="card"><h2>สถานะการจัดเก็บ</h2><p class="sub">${cloudMode?'เชื่อมต่อฐานข้อมูลแล้ว':'ยังเชื่อมต่อฐานข้อมูลไม่สำเร็จ'}</p><button class="btn" data-action="refresh-cloud">โหลดข้อมูลล่าสุด</button><p class="hint">ตั้งค่าการเชื่อมต่อไว้ในไฟล์โค้ดของระบบ</p></div></div>`;}
function render(){normalizeState(state);localStorage.setItem('pn-weekly-filters',JSON.stringify({year,funding}));applyBrand();if(!state.years.includes(year))year=state.years[0];if(report().id==='EMPTY'||(!report().year&&!rowsFor({...state,activeFunding:funding},report(),year).length)||(report().year&&report().year!==year)||((report().funding||'DOH')!==funding))selected=state.reports.find(r=>r.id!=='EMPTY'&&(r.funding||'DOH')===funding&&(r.year===year||(!r.year&&rowsFor({...state,activeFunding:funding},r,year).length)))?.id;const r=report();$('#crumb').textContent=names[view];$('#pending-count').textContent=activeRows().filter(x=>!complete(x.e)).length;$('#storage-status').innerHTML=cloudMode?'เชื่อมต่อฐานข้อมูล<small>พื้นที่ข้อมูลเดียว · ไม่ต้องเข้าสู่ระบบ</small>':'จัดเก็บบนอุปกรณ์นี้<small>สำรองข้อมูลได้จากเมนูตั้งค่า</small>';$('#mode-tag').textContent=cloudMode?'ฐานข้อมูล · เชื่อมต่อแล้ว':'ข้อมูลบนอุปกรณ์นี้';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#app').innerHTML=({dashboard,weekly,projects,reports,catalog,audit,settings}[view])();bind();}
function confirmAction(title,message,fn){modal(title,`<p class="sub">${esc(message)}</p><form>${buttons('ยืนยัน')}</form>`,fn);}
function editWeek(){const r=report();modal('แก้ไขช่วงสัปดาห์รายงาน',`<form><div class="form-grid">${field('วันเริ่มรอบ (อังคาร)','start',r.start,'date','required')}${field('วันสิ้นสุด (จันทร์)','end',r.end,'date','required')}</div><p class="hint">แก้ได้เฉพาะฉบับร่างล่าสุด เปอร์เซ็นต์สะสมคงเดิมและตรวจยืนยันใหม่</p>${buttons('บันทึกช่วงวันที่')}</form>`,f=>mutate('แก้ไขสัปดาห์รายงาน',s=>changeDraftWeek(s,r.id,{start:f.get('start'),end:f.get('end')})));}
function cancelWeek(){const r=report();if(r.locked)return toast('ยกเลิกได้เฉพาะฉบับร่าง รายงานที่ปิดแล้วเก็บประวัติไว้',true);confirmAction('ยืนยันยกเลิกสัปดาห์รายงาน','ลบฉบับร่างนี้และผลงานที่กรอกในสัปดาห์นี้ รายงานเดิมอื่นๆคงอยู่',async()=>{await mutate('ยกเลิกสัปดาห์รายงาน',s=>{if(s.reports.some(x=>x.id!==r.id&&x.end>r.end&&x.year===r.year&&(x.funding||'DOH')===funding))throw Error('มีสัปดาห์ถัดไปแล้ว ยกเลิกได้เฉพาะฉบับร่างล่าสุด');s.reports=s.reports.filter(x=>x.id!==r.id);if(!s.reports.length)s.reports.push(clone(BOOTSTRAP.reports[0]));});selected=state.reports.find(x=>x.end)?.id;render();});}
function newReport(){const last=state.reports.filter(r=>r.end&&(r.year===year||(!r.year&&rowsFor({...state,activeFunding:funding},r,year).length))&&(r.funding||'DOH')===funding).sort((a,b)=>b.end.localeCompare(a.end))[0];const range=last?{start:addDays(last.start,7),end:addDays(last.end,7)}:rangeFor(today());modal('สร้างสัปดาห์รายงาน',`<p class="sub">ระบบดึงข้อมูลล่าสุดที่เกิดก่อนสัปดาห์นี้ให้ทุกสัญญาในปี ${year}</p><form><div class="form-grid">${field('วันเริ่มรอบ (อังคาร)','start',range.start,'date','required')}${field('วันสิ้นสุด / วันอ้างอิง (จันทร์)','end',range.end,'date','required')}</div><p class="hint">ผลงานรายสัปดาห์เริ่มที่ 0 และรอยืนยันทุกแถว</p>${buttons('สร้างและเปิดสัปดาห์รายงาน')}</form>`,async f=>{let id;await mutate('สร้างสัปดาห์รายงาน',s=>{const r=createReport(s,{start:f.get('start'),end:f.get('end'),reference:f.get('end')},year,funding);id=r.id;s.reports.unshift(r);});selected=id;view='weekly';filter='ongoing';render();});}
function projectDialog(id){ensureRegistry(state);const r=id?state.contractRegistry.find(r=>r.projectId===id||r.id===id):null;registryEditDialog(r?.id);}
function extensionDialog(id){const p=state.projects.find(p=>p.id===id);modal('บันทึกการขยายสัญญา',`<form><div class="form-grid">${field('เลขหนังสืออนุมัติ','reference','','text','required')}${field('วันที่อนุมัติ','approvedAt',today(),'date','required')}${field('จำนวนวันเพิ่ม','days',7,'number','min="1" step="1" required')}${field('วันสิ้นสุดตามหนังสือ','end',addDays(p.end,7),'date','required')}</div><p class="hint">วันสิ้นสุดใหม่ต้องตรงกับวันสิ้นสุดปัจจุบัน + จำนวนวันที่เพิ่ม ระบบจะตรวจความสอดคล้องก่อนบันทึก</p>${buttons('บันทึกการอนุมัติ')}</form>`,f=>mutate('ขยายอายุสัญญา '+id,s=>{const p=s.projects.find(p=>p.id===id),n=+f.get('days');if(!Number.isInteger(n)||n<1||addDays(p.end,n)!==f.get('end'))throw Error('วันสิ้นสุดใหม่ไม่สอดคล้องกับจำนวนวันขยาย');if(p.extensions.some(e=>e.reference===f.get('reference').trim()))throw Error('เลขหนังสือนี้ถูกบันทึกแล้ว');p.extensions.push({id:crypto.randomUUID(),reference:f.get('reference').trim(),days:n,approvedAt:f.get('approvedAt'),end:f.get('end'),approved:true});p.end=f.get('end');}));const d=$('#modal [name=days]');d.oninput=()=>{$('#modal [name=end]').value=addDays(p.end,+d.value||0);};}
function preview(){const r=report();if((r.funding||'DOH')!==funding||(r.year&&r.year!==year))return toast('ยังไม่มีรายงานสำหรับกลุ่มงบและปีที่เลือก',true);if(!r.start||!r.end||!r.reference)return toast('รายงานต้นฉบับนี้ยังไม่มีช่วงวันที่ที่ตรวจสอบแล้ว กรุณาสร้างสัปดาห์ใหม่',true);modal('ตัวอย่างรายงานผู้บริหาร',`<div class="actions" style="margin-bottom:15px">${r.locked?'<button class="btn" id="amend-preview">แก้ไขรายงาน</button>':''}<button class="btn primary" id="print-report">↓ PDF / พิมพ์</button><button class="btn" id="xlsx-report">↓ Excel .xlsx</button><button class="btn" id="jpg-report">↓ รูปภาพ JPG</button></div>${!r.locked?'<div class="notice">ฉบับร่าง — ยังไม่ปิดรายงาน โปรดตรวจสอบก่อนนำเสนอ</div>':''}<div class="report-preview">${reportHTML({...state,activeFunding:funding},r,year)}</div>`);$('#modal').style.width='1150px';$('#amend-preview')?.addEventListener('click',()=>{$('#modal').close();amendDialog();});$('#print-report').onclick=()=>{let el=$('.print-report');if(!el){el=document.createElement('div');el.className='print-report';document.body.append(el);}el.innerHTML=reportHTML({...state,activeFunding:funding},r,year);$('#modal').close();window.print();};$('#jpg-report').onclick=async()=>{try{const n=await exportImages({...state,activeFunding:funding},r,year);toast('สร้างภาพแล้ว '+n+' หน้า หากดาวน์โหลดไม่ครบให้อนุญาตการดาวน์โหลดหลายไฟล์');}catch(e){toast(e.message,true);}};$('#xlsx-report').onclick=()=>download(xlsxBlob({...state,activeFunding:funding},r,year),'PN-weekly-'+year+'-'+funding+'-'+r.end+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}
function alerts(){const rows=activeRows();modal('รายการที่ควรตรวจสอบ',`<div class="notice">อายุสัญญาเทียบวันปัจจุบัน ${fmt(today())} ส่วนจำนวนวันดำเนินการเทียบจันทร์ท้ายสัปดาห์รายงาน</div>${rows.filter(x=>!complete(x.e)&&(expired(x.p)||x.e.plan>x.e.actual)).map(({p,e})=>`<div class="audit-item"><div><b>${esc(p.contract)} · ${esc(p.title)}</b><div class="sub">${expired(p)?'หมดอายุสัญญา '+fmt(p.end):''} · ผลงานต่ำกว่าแผน ${(e.plan-e.actual).toFixed(2)}%</div></div><button class="text-link" data-alert-edit="${p.id}">ดูสัญญา</button></div>`).join('')||'<div class="empty">ไม่พบรายการที่ต้องติดตาม</div>'}<h3 style="margin-top:20px">ข้อมูลนำเข้าที่ต้องทบทวน</h3>${(state.issues||[]).map(i=>`<div class="audit-item"><div><b>${esc(i.project)}</b><div class="sub">${esc(i.message)}<br>${esc(i.raw)}</div></div></div>`).join('')}<p class="sub">หัวรายงานเดิมระบุ พรบ.69 แต่เลขสัญญาเป็นปี 2568 • อ่านช่วงวันที่ได้ 56 จาก 57 รายงาน ส่วนรอบที่ 46 ต้องตรวจหัววันที่ในต้นฉบับ • หนังสือขยายสัญญาที่นำเข้ายังไม่มีเลขอ้างอิง</p>`);$$('[data-alert-edit]').forEach(b=>b.onclick=()=>{$('#modal').close();projectDialog(b.dataset.alertEdit);});}
function archivedDialog(){modal('สัญญาที่เก็บเข้าคลัง',state.projects.filter(p=>p.archived).map(p=>`<div class="catalog-item"><div>${esc(p.contract)} · ${esc(p.title)}</div><button class="btn" data-unarchive="${p.id}">นำกลับมาใช้งาน</button></div>`).join('')||'<div class="empty">ไม่มีสัญญาในคลัง</div>');$$('[data-unarchive]').forEach(b=>b.onclick=async()=>{try{await mutate('นำสัญญากลับมาใช้งาน '+b.dataset.unarchive,s=>s.projects.find(p=>p.id===b.dataset.unarchive).archived=false);$('#modal').close();}catch(e){toast(e.message,true);}});}
