function registrySummary(){const rows=registryVisibleRecords(),accounts=[...new Set(rows.map(r=>r.budgetAccount||'ยังไม่ระบุ'))].sort((a,b)=>a.localeCompare(b,'th'));return `<section class="register-summary" aria-label="สรุปทะเบียนสัญญา"><div class="summary-title"><h2>สรุปสัญญา</h2><span>${esc(fundingName(state,funding))} · ${year}</span></div><div class="summary-items"><button data-budget-filter="" class="summary-count ${!budgetFilter?'selected':''}"><span>ทั้งหมด</span><strong>${rows.length}</strong></button>${accounts.map(a=>`<button data-budget-filter="${esc(a)}" class="summary-count ${budgetFilter===a?'selected':''}"><span>${esc(a)}</span><strong>${rows.filter(r=>(r.budgetAccount||'ยังไม่ระบุ')===a).length}</strong></button>`).join('')}</div></section>`;}
